/** An `agent.deployed` event. `data.agent` is the agent. */
export type AgentEvent = {
  /** Unique id, prefixed `evt_`. Use it to ignore duplicates. */
  id: string;
  object: "event";
  type: "agent.deployed";
  /** Always `2026-11-11`, the only version, whatever the endpoint's `api_version`. */
  api_version: string;
  mode: Mode;
  /** When it happened. */
  created: string;
  /** The object the event is about, at the time of the event. */
  data: {
    agent: Agent;
  };
};

/** A `balance.*` event. `data.balance` is the balance. */
export type BalanceEvent = {
  /** Unique id, prefixed `evt_`. Use it to ignore duplicates. */
  id: string;
  object: "event";
  type: "balance.low" | "balance.topped_up";
  /** Always `2026-11-11`, the only version, whatever the endpoint's `api_version`. */
  api_version: string;
  mode: Mode;
  /** When it happened. */
  created: string;
  /** The object the event is about, at the time of the event. */
  data: {
    balance: Balance;
  };
};

/** Something that happened, as delivered to webhook endpoints. Kept 30 days. */
export type Event = ConversationEvent | MessageEvent | ContactEvent | ContactErasedEvent | OptOutEvent | AgentEvent | BalanceEvent;

export type EventList = {
  object: "list";
  /** Path of the list, such as `/v1/conversations`. */
  url: string;
  /** Whether there are more items after this page. */
  has_more: boolean;
  data: Array<Event>;
};

/** A URL that receives events. Live and test endpoints are separate. */
export type WebhookEndpoint = {
  /** Unique id, prefixed `we_`. */
  id: string;
  object: "webhook_endpoint";
  mode: Mode;
  /** HTTPS URL that receives the events. */
  url: string;
  /** What the endpoint is for. */
  description: string | null;
  enabled_events: EnabledEvents;
  /** `disabled` by you, or by Yesly after 50 failed deliveries in a row. A disabled endpoint gets no events and its pending retries are dropped. */
  status: "enabled" | "disabled";
  /** Stored as sent (default `2026-11-11`). Events are always rendered with `2026-11-11`. */
  api_version: string;
  created: string;
  /** Signing secret, `whsec_…`. Only returned when the endpoint is created or the secret is rolled. */
  secret?: string;
  /** When the previous secret stops working. Only returned when the secret is rolled. */
  previous_secret_expires_at?: string;
};

/** Event types sent to the endpoint. `["*"]` for all. */
export type EnabledEvents = Array<EventType | "*">;

export type WebhookEndpointCreate = {
  /** HTTPS URL on a public host, without a user name or password (`url_invalid` otherwise). Deliveries to a self-signed certificate fail. */
  url: string;
  enabled_events: EnabledEvents;
  /** Optional note. */
  description?: string;
  /** Stored and returned as sent; default `2026-11-11`. It does not change the events. */
  api_version?: string;
};

export type WebhookEndpointUpdate = {
  /** New URL. */
  url?: string;
  /** Replaces the list of event types. */
  enabled_events?: EnabledEvents;
  /** New note. */
  description?: string;
  /** `true` stops sending events to it and drops its pending retries. `false` enables it again and resets its count of failed deliveries. */
  disabled?: boolean;
};

export type WebhookEndpointList = {
  object: "list";
  /** Path of the list, such as `/v1/conversations`. */
  url: string;
  /** Whether there are more items after this page. */
  has_more: boolean;
  data: Array<WebhookEndpoint>;
};

/** What the endpoint answered to a test event. */
export type WebhookTest = {
  object: "webhook_test";
  /** Id of the test event sent, prefixed `evt_`. */
  event: string;
  /** HTTP status your endpoint answered with. `null` when there was no answer; see `error`. Redirects are not followed. */
  status_code: number | null;
  /** Time your endpoint took to answer. */
  duration_ms: number;
  /** Body your endpoint answered with, up to 2,000 characters. `null` when there was no answer. */
  response_body: string | null;
  /** Only when there was no answer. */
  error?: "timeout" | "address_not_allowed" | "connection_failed";
};

/** The prepaid balance. Test mode always returns a balance of 0 and never blocks. */
export type Balance = {
  object: "balance";
  mode: Mode;
  /** Balance left, in euros. */
  available: number;
  currency: string;
  /** Below this, `balance.low` fires. */
  low_balance_threshold: number;
  /** Not available yet. `enabled` is `false` and `below` and `amount` are `null`. */
  auto_top_up: {
    enabled: boolean;
    below: number | null;
    amount: number | null;
  };
};

/** `usage` (a charge), `top_up` (a card top-up) or `adjustment` (money given back, such as a refund for a message refused when sending, or taken back, negative, when a card top-up is refunded or disputed). */
export type BalanceTransactionType = "usage" | "top_up" | "adjustment";

/** A charge (`usage`), a top-up or an adjustment. Charges point to the agent, the conversation and the message, so you know what each agent and conversation cost. */
export type BalanceTransaction = {
  /** Unique id, prefixed `btx_`. */
  id: string;
  object: "balance_transaction";
  type: BalanceTransactionType;
  /** Channel charged, on `usage`. */
  channel?: Channel;
  /** In euros. Negative for charges, positive for top-ups and adjustments. */
  amount: number;
  /** Units charged, on `usage`. */
  quantity?: number;
  /** `message` for SMS, WhatsApp and email, `minute` for calls. */
  unit?: "message" | "minute";
  /** The agent charged, on `usage`. */
  agent?: string | null;
  /** The conversation charged, on `usage`; `null` for a message sent with Create a message. */
  conversation?: string | null;
  /** The message or call charged, on `usage`. */
  message?: string | null;
  /** Id of the Stripe invoice, on `top_up` when Stripe issued one. */
  invoice?: string;
  created: string;
};

export type BalanceTransactionList = {
  object: "list";
  /** Path of the list, such as `/v1/conversations`. */
  url: string;
  /** Whether there are more items after this page. */
  has_more: boolean;
  data: Array<BalanceTransaction>;
};

/** The conversations of one agent or one direction. */
export type AnalyticsSlice = {
  conversations: number;
  engaged: number;
  ended: number;
  no_reply: number;
  /** Conversations per outcome code, only codes with at least one. Outcome codes are each agent's own, so read them per agent. */
  outcomes: Record<string, number>;
  spend: {
    amount?: number;
    currency?: string;
  };
};

/** Conversations, outcomes, usage and spend. Conversations count on the day they were created, in your account's time zone. */
export type AnalyticsSummary = {
  object: "analytics_summary";
  range: "7d" | "30d" | "90d";
  from: string;
  to: string;
  conversations: number;
  /** Conversations by status. */
  statuses: {
    scheduled: number;
    in_progress: number;
    ended: number;
    no_reply: number;
    cancelled: number;
    failed: number;
  };
  /** Ended conversations by outcome code. */
  outcomes: Record<string, number>;
  /** Conversations where the contact answered a call or wrote back. */
  engaged: number;
  /** Conversations handed to a person. */
  transferred: number;
  /** Conversations by the last channel used. */
  by_channel: {
    call: number;
    sms: number;
    whatsapp: number;
    email: number;
  };
  /** Messages sent (not failed) and started call minutes. */
  usage: {
    call_minutes: number;
    sms_messages: number;
    whatsapp_messages: number;
    email_messages: number;
  };
  /** What the conversations cost. `0` in test mode. */
  spend: {
    amount: number;
    currency: string;
  };
  /** What was charged per channel in the range, from the ledger (refunds taken off). `0` in test mode. */
  spend_by_channel?: {
    call?: number;
    sms?: number;
    whatsapp?: number;
    email?: number;
  };
  /** Per agent id (only the key's agent for a key scoped to one), with the same filters. */
  by_agent?: Record<string, AnalyticsSlice>;
  /** Outbound and inbound, with the same filters. */
  by_direction?: {
    outbound?: AnalyticsSlice;
    inbound?: AnalyticsSlice;
  };
  /** One item per day of the range, oldest first. */
  days: Array<{
    date: string;
    conversations: number;
    engaged: number;
    ended: number;
    no_reply: number;
    /** What that day's conversations cost (0 in test mode). */
    spend: {
      amount?: number;
      currency?: string;
    };
  }>;
};

// Parameters of each operation.

export type AgentsUpdateParams = AgentUpdate;

export type SendersListParams = {
  /** Only this agent's senders. */
  agent?: string;
  /** Only this channel. */
  channel?: Channel;
};

export type ContactsListParams = {
  /** The contact with this `external_id`. */
  external_id?: string;
  /** The contact with this phone. */
  phone?: Phone;
  /** The contact with this email. */
  email?: string;
  /** Contacts whose name starts with this (two characters at least), ignoring case and accents, in name order. */
  name?: string;
  /** Between 1 and 100. Default 20. */
  limit?: number;
  /** Cursor: the id of the last item of the previous page. */
  starting_after?: string;
};

export type ContactsCreateParams = ContactInput;

export type ContactsUpdateParams = ContactUpdate;

export type ContactsMergeParams = ContactMerge;

export type ConversationsListParams = {
  /** Only this agent's. */
  agent?: string;
  /** Only this contact's. */
  contact?: string;
  /** Only in this status. */
  status?: ConversationStatus;
  /** Only `outbound` or only `inbound`. */
  direction?: "outbound" | "inbound";
  /** Only conversations whose current or last channel is this one. */
  channel?: "call" | "sms" | "whatsapp" | "email";
  /** Only conversations that ended with this outcome code. */
  outcome?: string;
  /** Created on or after this day or time. A day starts at 00:00 in your account's time zone. */
  from?: DateOrDateTime;
  /** Created on or before this day or time. A day ends at 23:59:59 in your account's time zone. */
  to?: DateOrDateTime;
  /** Between 1 and 100. Default 20. */
  limit?: number;
  /** Cursor: the id of the last item of the previous page. */
  starting_after?: string;
};

export type ConversationsCreateParams = ConversationCreate;

export type ConversationsRecordingParams = {
  /** The call, prefixed `msg_`. */
  message?: string;
};

export type MessagesListParams = {
  /** Only this conversation's. */
  conversation?: string;
  /** Only this contact's. */
  contact?: string;
  /** Between 1 and 100. Default 20. */
  limit?: number;
  /** Cursor: the id of the last item of the previous page. */
  starting_after?: string;
};

export type MessagesCreateParams = MessageCreate;

export type TemplatesListParams = {
  /** Only templates in this state. */
  status?: "pending" | "approved" | "rejected" | "paused" | "disabled";
};

export type TemplatesCreateParams = TemplateCreate;

export type OptOutsListParams = {
  /** Only this channel. */
  channel?: OptOutChannel;
  /** Only this phone or email. */
  address?: string;
  /** The opt-outs of every phone and email of this contact. */
  contact?: string;
  /** Between 1 and 100. Default 20. */
  limit?: number;
  /** Cursor: the id of the last item of the previous page. */
  starting_after?: string;
};

export type OptOutsCreateParams = OptOutCreate;

export type AnalyticsSummaryParams = {
  /** Days covered, ending today. */
  range?: "7d" | "30d" | "90d";
  /** Only this agent's conversations. */
  agent?: string;
  /** Only conversations whose last channel is this one. */
  channel?: Channel;
  /** Only `outbound` or only `inbound`. */
  direction?: "outbound" | "inbound";
};

export type BalanceListTransactionsParams = {
  /** `usage`, `top_up` or `adjustment`. */
  type?: BalanceTransactionType;
  /** Only charges of this agent. */
  agent?: string;
  /** Only charges of this conversation. */
  conversation?: string;
  /** On or after this day or time. A day alone means 00:00 UTC. */
  from?: DateOrDateTime;
  /** On or before this day or time. A day alone means 23:59:59 UTC. */
  to?: DateOrDateTime;
  /** Between 1 and 100. Default 20. */
  limit?: number;
  /** Cursor: the id of the last item of the previous page. */
  starting_after?: string;
};

export type WebhookEndpointsCreateParams = WebhookEndpointCreate;

export type WebhookEndpointsUpdateParams = WebhookEndpointUpdate;

export type WebhookEndpointsTestParams = {
  /** Event type to simulate. */
  type?: EventType;
};

export type EventsListParams = {
  /** Only this event type, matched exactly. */
  type?: string;
  /** Only events about this conversation and its messages. */
  conversation?: string;
  /** Only events about this contact and its opt-outs. */
  contact?: string;
  /** Events created on or after this time. A day alone means 00:00 UTC. */
  from?: DateOrDateTime;
  /** Between 1 and 100. Default 20. */
  limit?: number;
  /** Cursor: the id of the last item of the previous page. */
  starting_after?: string;
};
